@@ -5,3 +5,9 @@ export function isValidEmail(input: string): boolean {
   return EMAIL.test(input);
 }
+
+export function isValidUsername(name: string): boolean {
+  if (name === "" || name === "ab") return false;
+  if (name.length > 20) return false;
+  return /^\w+$/.test(name);
+}
